    exp_t e;
    if (exp.exists(p.uid())) `uvm_error("DUPIN", p.uid())
    e.p = p; e.legal = route(p); e.seen = '0;
    exp[p.uid()] = e;
  endfunction

  function void write_out(pkt p);
    string id = p.uid();
    if (!exp.exists(id))                    begin `uvm_error("UNEXP", id) return; end
    if (!exp[id].legal[p.port])             `uvm_error("ROUTE", $sformatf("%s on port %0d", id, p.port))
    else if (exp[id].seen[p.port])          `uvm_error("DUP",   $sformatf("%s twice on %0d", id, p.port))
    else if (p.payload != exp[id].p.payload) `uvm_error("DATA",  id)
    else if (p.t - exp[id].p.t > max_lat)   `uvm_error("LAT",   id)
    else n_ok++;
    exp[id].seen[p.port] = 1;
    if (exp[id].seen == exp[id].legal) exp.delete(id);   // all copies delivered
  endfunction

  function void check_phase(uvm_phase phase);
    foreach (exp[id]) `uvm_error("DROP", $sformatf("%s missing ports %b", id, exp[id].legal & ~exp[id].seen))
  endfunction
endclass
```

### Explanation
- A unique ID makes the checker independent of interleaving across 20 outputs. If the DUT keeps per-flow order, also check that `seq` increases per (src, out port).
- When packets carry no ID, match by a payload hash within the legal output set, and handle identical payloads carefully (FIFO per hash).

### Corner cases & pitfalls
- Reset mid-traffic: bump an `epoch` so stale packets are not confused with new ones that reuse sequence numbers.
- Unicast routes where the route is "any of N" (load balancing): `legal` has N bits, but exactly one delivery is expected. Delete on the first match.
- Coverage: every input × output pair, contention (several inputs to one output), back-pressure on outputs.

### Follow-ups
- *Scale to many ports?* Use a parameterized array of analysis imps (or one imp with the port in the transaction), as here.

tongxin-224:
**Key idea:** The top module instantiates the interface and the DUT. **Before** `run_test()`, it publishes the virtual interface with `uvm_config_db#(virtual my_if)::set`. Each driver or monitor retrieves it in `build_phase` (check the return value and `uvm_fatal` on failure). The monitor's analysis port is connected to its subscribers in `connect_phase`. The type and modport in `set` and `get` must match exactly.

```mermaid
sequenceDiagram
  participant TOP as tb_top (module)
  participant DB as uvm_config_db
  participant MON as monitor (build_phase)
  participant ENV as env (connect_phase)
  TOP->>DB: set(null, "uvm_test_top.env.agt*", "vif", bus_if_inst)
  TOP->>TOP: run_test()
  MON->>DB: get(this, "", "vif", vif)
  DB-->>MON: virtual bus_if handle
  ENV->>ENV: agt.mon.ap.connect(sb.imp)
```

### Code
```systemverilog
interface bus_if (input logic clk);
  logic        rst_n, valid, ready;
  logic [31:0] data;
  clocking mon_cb @(posedge clk); input rst_n, valid, ready, data; endclocking
  modport MON (clocking mon_cb);
endinterface

module tb_top;
  import uvm_pkg::*;
  logic clk = 0; always #5 clk = ~clk;
  bus_if bif (clk);
  dut u_dut (.clk(clk), .rst_n(bif.rst_n), .valid(bif.valid),
             .ready(bif.ready), .data(bif.data));
  initial begin
    uvm_config_db #(virtual bus_if)::set(null, "uvm_test_top.env.agt*", "vif", bif);
    run_test();
  end
endmodule

class bus_monitor extends uvm_monitor;
  `uvm_component_utils(bus_monitor)
  virtual bus_if vif;
  uvm_analysis_port #(bus_tr) ap;
  function new(string name, uvm_component parent); super.new(name, parent); endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    ap = new("ap", this);
    if (!uvm_config_db #(virtual bus_if)::get(this, "", "vif", vif))
      `uvm_fatal("NOVIF", {"vif not set for ", get_full_name()})
  endfunction

  task run_phase(uvm_phase phase);
    forever begin
      @(vif.mon_cb);
      if (vif.mon_cb.rst_n && vif.mon_cb.valid && vif.mon_cb.ready) begin
        bus_tr t = bus_tr::type_id::create("t");
        t.data = vif.mon_cb.data;
        ap.write(t);
      end
    end
  endtask
endclass

// in env::connect_phase
//   agt.mon.ap.connect(sb.analysis_export);
//   agt.mon.ap.connect(cov.analysis_export);
```

### Corner cases & pitfalls
- `set` with type `virtual bus_if` and `get` with `virtual bus_if.MON` are **different types**, so `get` fails. Use the same one in both places.
- Calling `set` after `run_test()` in the same initial block never executes in time, because `run_test` blocks.
- Path typo in `set` → `get` returns 0. Debug with `+UVM_CONFIG_DB_TRACE`.
- Do not create the transaction once outside the loop and reuse it. Subscribers would see it overwritten.

### Follow-ups
- *Many instances of the same interface?* Use distinct paths per agent (`env.agt0`, `env.agt1`) or keys (`"vif0"`), set in a `generate` loop.

