  end
endmodule

// config-object style (recommended for large envs)
class base_test extends uvm_test;
  `uvm_component_utils(base_test)
  axi_agent_cfg axi_cfg;
  function new(string name, uvm_component parent); super.new(name, parent); endfunction
  function void build_phase(uvm_phase phase);
    axi_cfg = axi_agent_cfg::type_id::create("axi_cfg");
    if (!uvm_config_db #(virtual axi_if)::get(this, "env.axi_agt", "vif", axi_cfg.vif))
      `uvm_fatal("VIF", "axi vif not found")
